using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;
using System.Web.Script.Serialization;

// Original lossless DeviceSetting_V2 reader/writer. Format research is credited
// in assets/skill-slots/README.md. This edits local HUD settings, never memory.
internal static class NativeHudFile {
 internal static readonly string[] Tags={"QuickSlotSkill1","QuickSlotSkill2","QuickSlotStigma"};
 static readonly byte[] Mask={0x25,0xa8,0x7e,0x91};
 static readonly UTF8Encoding Utf8=new UTF8Encoding(false,true);
 internal sealed class Record {internal int Start,End,SizeAt;internal string Identity,Text;internal Dictionary<string,object> Value;}
 internal sealed class Document {internal byte[] Clear;internal readonly List<Record> Records=new List<Record>();internal readonly List<Group> Groups=new List<Group>();}
 internal sealed class Group {internal string Key;internal Record Record;internal Dictionary<string,object>[] Rows;internal int Preset;}
 internal sealed class Patch {internal byte[] Bytes;internal Dictionary<string,bool> Restore;internal bool Changed,AllHidden;internal int Groups;}
 internal static string Hash(byte[] b){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(b)).Replace("-","");}
 static byte[] Crypt(byte[] b){var a=new byte[b.Length];for(int n=0;n<b.Length;n++)a[n]=(byte)(b[n]^Mask[n%4]);return a;}
 internal static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=4*1024*1024,RecursionLimit=64};}
 static InvalidDataException Unsupported(){return new InvalidDataException("Unsupported HUD settings format; no changes were made.");}
 static int End(byte[] b,int at){int depth=0;bool quoted=false,escape=false;for(int n=at;n<b.Length;n++){byte c=b[n];if(escape){escape=false;continue;}if(quoted&&c==92){escape=true;continue;}if(c==34)quoted=!quoted;if(!quoted){if(c==123)depth++;else if(c==125&&--depth==0)return n+1;}}throw Unsupported();}
 internal static string Canonical(object value){var dict=value as Dictionary<string,object>;if(dict!=null)return "{"+string.Join(",",dict.OrderBy(p=>p.Key,StringComparer.Ordinal).Select(p=>Json().Serialize(p.Key)+":"+Canonical(p.Value)))+"}";var array=value as object[];if(array!=null)return "["+string.Join(",",array.Select(Canonical))+"]";var list=value as ArrayList;if(list!=null)return "["+string.Join(",",list.Cast<object>().Select(Canonical))+"]";return Json().Serialize(value);}
 static Dictionary<string,object> Object(object o){var value=o as Dictionary<string,object>;if(value==null)throw Unsupported();return value;}
 internal static Document Read(byte[] bytes){if(bytes==null||bytes.Length<8||bytes.Length>4*1024*1024)throw Unsupported();var d=new Document{Clear=Crypt(bytes)};int first=BitConverter.ToInt32(d.Clear,0);if(first<2||first>d.Clear.Length-4||d.Clear[4]!=123||d.Clear[4+first-1]!=0||End(d.Clear,4)!=4+first-1)throw Unsupported();var global=Object(Json().DeserializeObject(Utf8.GetString(d.Clear,4,first-1)));if(!global.ContainsKey("Version"))throw Unsupported();int p=4+first;var identities=new HashSet<string>();
  while(p<d.Clear.Length){int start=-1;for(int n=p;n<Math.Min(d.Clear.Length-2,p+68);n++)if(d.Clear[n]==123&&d.Clear[n+1]==13&&d.Clear[n+2]==10){start=n;break;}if(start<0){if(d.Clear.Length-p<=16&&d.Clear.Skip(p).All(b=>b==0))break;throw Unsupported();}if(start-p<12||(start-p)%4!=0)throw Unsupported();int end=End(d.Clear,start);if(end>=d.Clear.Length||d.Clear[end]!=0||BitConverter.ToInt32(d.Clear,start-4)!=end-start+1)throw Unsupported();string text=Utf8.GetString(d.Clear,start,end-start);var value=Object(Json().DeserializeObject(text));if(!value.ContainsKey("Version"))throw Unsupported();string identity=BitConverter.ToString(d.Clear,start-12,8).Replace("-","");var record=new Record{Start=start,End=end,SizeAt=start-4,Identity=identity,Text=text,Value=value};d.Records.Add(record);if(d.Records.Count>512)throw Unsupported();object presets;
   if(value.TryGetValue("HudEditPreset",out presets)){if(!identities.Add(identity))throw Unsupported();var items=presets as object[];if(items==null||items.Length!=6)throw Unsupported();for(int index=0;index<items.Length;index++){var preset=Object(items[index]);object edits;if(!preset.TryGetValue("Edit",out edits))throw Unsupported();var edit=Object(edits);if(edit.Count==0)continue;var rows=new Dictionary<string,object>[3];for(int n=0;n<3;n++){object row;if(!edit.TryGetValue(Tags[n],out row))throw Unsupported();rows[n]=Object(row);object tag,hide;if(!rows[n].TryGetValue("Tag",out tag)||Convert.ToString(tag)!=Tags[n]||!rows[n].TryGetValue("Hide",out hide)||!(hide is bool))throw Unsupported();}d.Groups.Add(new Group{Key=identity+"/"+index,Record=record,Preset=index,Rows=rows});}}
   p=end+1;
  }if(d.Groups.Count==0)throw new InvalidDataException("Save a HUD preset in the game first. No changes were made.");return d;
 }
 internal static Patch Build(byte[] before,bool hide,Dictionary<string,bool> previous){var d=Read(before);var restore=new Dictionary<string,bool>(previous??new Dictionary<string,bool>());var replacements=new Dictionary<Record,string>();bool all=true;
  foreach(var group in d.Groups){bool changeGroup=hide;for(int n=0;n<3;n++){string key=group.Key+"/"+Tags[n];if(changeGroup&&!restore.ContainsKey(key))restore[key]=(bool)group.Rows[n]["Hide"];bool old;group.Rows[n]["Hide"]=hide?true:restore.TryGetValue(key,out old)?old:restore.Count>0?(bool)group.Rows[n]["Hide"]:false;all&=(bool)group.Rows[n]["Hide"];}}
  foreach(var record in d.Records.Where(r=>d.Groups.Any(g=>g.Record==r))){var queues=Tags.ToDictionary(tag=>tag,tag=>new Queue<bool>(d.Groups.Where(g=>g.Record==record).Select(g=>(bool)g.Rows[Array.IndexOf(Tags,tag)]["Hide"])));var spans=new List<Tuple<int,int,string>>();foreach(Match match in Regex.Matches(record.Text,"\\{\\s*\"Tag\"\\s*:\\s*\"(QuickSlotSkill1|QuickSlotSkill2|QuickSlotStigma)\"")){string tag=match.Groups[1].Value;if(queues[tag].Count==0)throw Unsupported();int byteStart=Utf8.GetByteCount(record.Text.Substring(0,match.Index));var rawText=Utf8.GetBytes(record.Text);int byteEnd=End(rawText,byteStart);int length=Utf8.GetCharCount(rawText,byteStart,byteEnd-byteStart);string row=record.Text.Substring(match.Index,length);var flags=Regex.Matches(row,"\"Hide\"\\s*:\\s*(true|false)\\b");if(flags.Count!=1)throw Unsupported();var flag=flags[0].Groups[1];spans.Add(Tuple.Create(match.Index+flag.Index,flag.Length,queues[tag].Dequeue()?"true":"false"));}if(queues.Values.Any(q=>q.Count!=0))throw Unsupported();string text=record.Text;foreach(var span in spans.OrderByDescending(v=>v.Item1))text=text.Remove(span.Item1,span.Item2).Insert(span.Item1,span.Item3);if(Canonical(Json().DeserializeObject(text))!=Canonical(record.Value))throw Unsupported();replacements[record]=text;}
  using(var output=new MemoryStream()){int cursor=0;foreach(var record in d.Records){string text;if(!replacements.TryGetValue(record,out text))continue;byte[] payload=Utf8.GetBytes(text);output.Write(d.Clear,cursor,record.SizeAt-cursor);byte[] length=BitConverter.GetBytes(payload.Length+1);output.Write(length,0,4);output.Write(payload,0,payload.Length);output.WriteByte(0);cursor=record.End+1;}output.Write(d.Clear,cursor,d.Clear.Length-cursor);byte[] result=Crypt(output.ToArray());var verify=Read(result);if(verify.Groups.Count!=d.Groups.Count||verify.Records.Count!=d.Records.Count)throw Unsupported();for(int n=0;n<d.Records.Count;n++)if(Canonical(verify.Records[n].Value)!=Canonical(d.Records[n].Value))throw Unsupported();return new Patch{Bytes=result,Restore=hide?restore:new Dictionary<string,bool>(),Changed=!before.SequenceEqual(result),AllHidden=all,Groups=d.Groups.Count};}
 }
}

internal sealed class NativeHotbar {
 internal sealed class Journal {public int Version=1;public string Path,LastBackup,BeforeHash,AfterHash;public Dictionary<string,bool> Restore=new Dictionary<string,bool>();}
 readonly string root,backupRoot;readonly bool preview;readonly Func<bool> running;bool configured,pending;bool? desired;string configuredPath="",path="",message="",fault;double last=-100,closedAt=-1,observedAt=-100;DateTime observedStamp;long observedSize=-1;bool? observed;Journal journal;internal long Revision;
 internal NativeHotbar(string root,bool preview=false,Func<bool> running=null,string backups=null){this.root=root;this.preview=preview;this.running=running??IntroTweaks.Running;backupRoot=backups??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Aion2Helper","HotbarBackups");}
 internal bool? Observed {get{return observed;}}internal string PathName {get{return path;}}internal string Message {get{return message;}}internal bool Pending {get{return pending;}}internal string BackupDirectory {get{return string.IsNullOrEmpty(path)?backupRoot:Path.Combine(backupRoot,NativeHudFile.Hash(Encoding.UTF8.GetBytes(path.ToUpperInvariant())));}}
 void Status(string text){if(message==text)return;message=text;Revision++;}
 internal void Configure(bool? value,string requestedPath){requestedPath=requestedPath??"";if(configured&&desired==value&&configuredPath==requestedPath)return;bool initial=!configured,changedPath=configuredPath!=requestedPath;configured=true;desired=value;configuredPath=requestedPath;fault=null;closedAt=-1;
  if(preview){pending=false;Status("Game hotbar preview; no game settings are changed.");return;}
  try{if(initial||changedPath){path=SelectPath(requestedPath);observedSize=-1;observed=null;journal=LoadJournal();Probe(true);}pending=value==true||(!initial&&value.HasValue)||journal!=null&&journal.Restore.Count>0;if(pending)Status(value==true?"Hide pending. Close AION 2 to apply it automatically.":"Restore pending. Close AION 2 to apply it automatically.");else Status(observed==true?"Game hotbar is already hidden.":"Game hotbar is visible.");}catch(Exception ex){Fail(ex);}
 }
 string SelectPath(string selected){if(!string.IsNullOrWhiteSpace(selected))return Validate(selected);string config=Path.Combine(root,"visual-tweaks.json");if(File.Exists(config)){var o=NativeHudFile.Json().Deserialize<Dictionary<string,object>>(File.ReadAllText(config));object value;if(o!=null&&o.TryGetValue("ConfigPath",out value)&&value is string){string windows=Path.GetDirectoryName((string)value);if(!string.IsNullOrEmpty(windows)){var parent=Directory.GetParent(windows);if(parent!=null&&parent.Parent!=null){string candidate=Path.Combine(parent.Parent.FullName,"PersistentDownloadDir","UserSetting","DeviceSetting_V2.dat");if(File.Exists(candidate))return Validate(candidate);}}}}
  string game=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"AION2");if(!Directory.Exists(game))throw new IOException("AION 2 HUD settings were not found.");var files=Directory.GetDirectories(game).Take(64).Select(d=>Path.Combine(d,"PersistentDownloadDir","UserSetting","DeviceSetting_V2.dat")).Where(File.Exists).ToArray();if(files.Length!=1)throw new IOException(files.Length==0?"AION 2 HUD settings were not found.":"Several AION 2 installations were found. Select the settings file.");return Validate(files[0]);
 }
 static string Validate(string value){string p=Path.GetFullPath(value);if(!string.Equals(Path.GetFileName(p),"DeviceSetting_V2.dat",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Select DeviceSetting_V2.dat.");VisualTweaks.NoLinks(p);if(!File.Exists(p)||new FileInfo(p).Length>4*1024*1024)throw new IOException("AION 2 HUD settings were not found.");return p;}
 string JournalPath {get{return Path.Combine(BackupDirectory,"active.json");}}
 Journal LoadJournal(){if(!File.Exists(JournalPath))return new Journal{Path=path};VisualTweaks.NoLinks(JournalPath);if(new FileInfo(JournalPath).Length>1024*1024)throw new InvalidDataException("The HUD restore record is invalid. The game settings were not changed.");var j=NativeHudFile.Json().Deserialize<Journal>(File.ReadAllText(JournalPath));if(j==null||j.Version!=1||!string.Equals(j.Path,path,StringComparison.OrdinalIgnoreCase)||j.Restore==null||j.Restore.Count>9216)throw new InvalidDataException("The HUD restore record is invalid. The game settings were not changed.");return j;}
 internal static void Atomic(string target,byte[] bytes){string temp=target+".aion2helper-"+Guid.NewGuid().ToString("N")+".tmp";try{using(var f=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){f.Write(bytes,0,bytes.Length);f.Flush(true);}if(File.Exists(target))File.Replace(temp,target,null);else File.Move(temp,target);}finally{if(File.Exists(temp))File.Delete(temp);}}
 void Probe(bool force){if(string.IsNullOrEmpty(path))return;var info=new FileInfo(path);if(!force&&info.LastWriteTimeUtc==observedStamp&&info.Length==observedSize)return;byte[] bytes=File.ReadAllBytes(Validate(path));var doc=NativeHudFile.Read(bytes);observed=doc.Groups.All(g=>g.Rows.All(r=>(bool)r["Hide"]));observedStamp=info.LastWriteTimeUtc;observedSize=info.Length;Revision++;}
 internal void Inspect(double now){if(preview||fault!=null||now-observedAt<2)return;observedAt=now;try{Probe(false);}catch(Exception ex){Fail(ex);}}
 internal void Retry(){fault=null;observedSize=-1;last=-100;closedAt=-1;try{path=SelectPath(configuredPath);journal=LoadJournal();Probe(true);pending=desired.HasValue||journal.Restore.Count>0;Status(pending?"Waiting for AION 2 to close.":observed==true?"Game hotbar is already hidden.":"Game hotbar is visible.");}catch(Exception ex){Fail(ex);}}
 internal void Maintain(double now){if(preview||!configured||fault!=null||(!pending&&desired!=true)||now-last<2)return;last=now;try{if(running()){closedAt=-1;if(pending)Status(desired==true?"Hide pending. Close AION 2 to apply it automatically.":"Restore pending. Close AION 2 to apply it automatically.");return;}if(closedAt<0){closedAt=now;return;}if(now-closedAt<2)return;Probe(false);if(!pending&&desired==true&&observed==true)return;Apply();}catch(Exception ex){Fail(ex);}}
 // Serialize changes from multiple Helper windows/copies; reload the journal
 // inside the lock, then check both the game and source again before commit.
 void Apply(){using(var mutex=new Mutex(false,"Local\\Aion2Helper-Hotbar-"+Path.GetFileName(BackupDirectory))){bool owned=false;try{try{owned=mutex.WaitOne(0);}catch(AbandonedMutexException){owned=true;}if(!owned)return;ApplyLocked();}finally{if(owned)mutex.ReleaseMutex();}}}
 void ApplyLocked(){if(running())throw new IOException("AION 2 is running; the HUD settings were not changed.");byte[] before=File.ReadAllBytes(Validate(path));journal=LoadJournal();var patch=NativeHudFile.Build(before,desired==true,journal.Restore);if(patch.Changed){VisualTweaks.NoLinks(backupRoot);Directory.CreateDirectory(BackupDirectory);VisualTweaks.NoLinks(BackupDirectory);string backup=Path.Combine(BackupDirectory,DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fffffff")+"-"+NativeHudFile.Hash(before).Substring(0,12)+".dat");using(var f=new FileStream(backup,FileMode.CreateNew,FileAccess.Write,FileShare.Read)){f.Write(before,0,before.Length);f.Flush(true);}if(!File.ReadAllBytes(backup).SequenceEqual(before))throw new IOException("HUD backup verification failed. The game settings were not changed.");
   var prepared=new Journal{Path=path,LastBackup=backup,BeforeHash=NativeHudFile.Hash(before),AfterHash=NativeHudFile.Hash(patch.Bytes),Restore=desired==true?patch.Restore:journal.Restore};Atomic(JournalPath,Encoding.UTF8.GetBytes(NativeHudFile.Json().Serialize(prepared)));
   if(running()||!File.ReadAllBytes(Validate(path)).SequenceEqual(before))throw new IOException("AION 2 settings changed during preparation. Nothing was applied; retry after closing the game.");Atomic(path,patch.Bytes);if(!File.ReadAllBytes(path).SequenceEqual(patch.Bytes))throw new IOException("HUD verification failed. The original backup was preserved.");journal=prepared;
  }journal.Restore=patch.Restore;if(patch.Restore.Count>0){VisualTweaks.NoLinks(BackupDirectory);Directory.CreateDirectory(BackupDirectory);}if(Directory.Exists(BackupDirectory))Atomic(JournalPath,Encoding.UTF8.GetBytes(NativeHudFile.Json().Serialize(journal)));pending=false;Probe(true);Status(desired==true?"Game hotbar hidden. Other HUD elements were preserved.":"Previous hotbar visibility restored. Other HUD elements were preserved.");
 }
 void Fail(Exception ex){if(!(ex is IOException||ex is InvalidDataException||ex is UnauthorizedAccessException||ex is ArgumentException||ex is InvalidOperationException||ex is System.Security.SecurityException))throw ex;fault=ex.Message;Status(fault);}
 internal object Diagnostic {get{return new{requested=desired,observedHidden=observed,pending,settingsFile=path,backup=journal==null?null:journal.LastBackup,message,fault};}}
}
